import {
  debounce,
  checkEmail,
  validatePassword,
  updateCooldown,
  startCooldown,
  parseDuration,
} from '/static/js/common/functions.prod.js';
import {
  showOutput,
  showSuccessMessage,
  clearOutput,
  showErrorMessage,
} from '/static/js/common/notification.prod.js';
document.addEventListener('DOMContentLoaded', function () {
  let e = $('[name="csrftoken"]')[0].content;
  (updateCooldown(),
    $.ajaxPrefilter(function (e, t, a) {
      localStorage.getItem('login_cooldown_until') &&
        (updateCooldown(), a.abort());
    }),
    $('main').on(
      'input',
      '#username',
      debounce(function (e) {
        const t = e.target.value
          .toLowerCase()
          .trim()
          .replace(/[^a-zA-Z0-9_]/g, '');
        ((e.target.value = t),
          t.length <= 4
            ? showOutput('Username too short.')
            : t.length > 12
              ? showOutput('Username too long.')
              : $.ajax({
                  type: 'GET',
                  url: `/?action=check_username&username=${t}`,
                  success: function (e) {
                    'valid' == e.status
                      ? showOutput('Username is unique.', !0)
                      : showOutput('Username already taken.');
                  },
                }));
      })
    ),
    $('main').on('click', '#formButton', function () {
      let t = !1;
      if (
        ($('input').each(function () {
          if ($(this).val().trim().length <= 0)
            return (
              showErrorMessage(
                'Empty Fields',
                'Kindly fill the input with information'
              ),
              void (t = !0)
            );
        }),
        t)
      )
        return void (t = !1);
      let a = $('#username'),
        o = $('#email'),
        s = $('#fullOtp'),
        n = $('#password1'),
        r = $('#reppassword1'),
        i = $('#password2'),
        l = $('#reppassword2'),
        u = $('#login_email'),
        c = $('#login_password'),
        d = $('#reset_email');
      if (a.length) {
        let t = a.val().trim();
        $.ajax({
          type: 'POST',
          headers: { 'X-CSRFToken': e },
          url: '/?action=update_username',
          data: JSON.stringify({ username: t }),
          success: function (e) {
            e.status
              ? (showSuccessMessage(
                  'Username Changed',
                  'You have successfully updated your username.'
                ),
                window.location.reload())
              : showErrorMessage(
                  'Error',
                  'Your username could not be changed.'
                );
          },
        });
      } else if (o.length)
        $.ajax({
          type: 'POST',
          headers: { 'X-CSRFToken': e },
          data: JSON.stringify({ email: o.val().trim() }),
          url: '/?action=verify_email',
          success: function (e) {
            $('#formContent').empty().append(e);
          },
        });
      else if (s.length) {
        if (s.val().trim().length < 5)
          return void showErrorMessage(
            'Invalid OTP',
            'The OTP is 6 digits long.'
          );
        $.ajax({
          type: 'POST',
          url: '?action=validate_email',
          headers: { 'X-CSRFToken': e },
          data: JSON.stringify({ otp: s.val().trim() }),
          success: function (e) {
            let t = e.status;
            'social_auth' != t
              ? t
                ? (showSuccessMessage(
                    'OTP Correct!',
                    'Validating your details'
                  ),
                  $('#formContent').empty().append(e.html))
                : showErrorMessage(
                    'Invalid OTP!',
                    'Confirm you are entering the latest password and it has not expired.'
                  )
              : (window.location.href = e.url);
          },
        });
      } else if (n.length && i.length) {
        let t = n.val().trim();
        t == i.val().trim() &&
          $.ajax({
            type: 'POST',
            url: '?action=create_account',
            headers: { 'X-CSRFToken': e },
            data: JSON.stringify({ password: t }),
            success: function (e) {
              e.status
                ? (showOutput('Details Saved', 'Log into your account.'),
                  window.location.reload())
                : showErrorMessage('Error Occurred', 'Try creating again.');
            },
          });
      } else if (u.length && c.length) {
        let t = u.val().trim(),
          a = c.val().trim();
        $.ajax({
          type: 'POST',
          url: '?action=login_user',
          headers: { 'X-CSRFToken': e },
          data: JSON.stringify({ email: t, password: a }),
          success: function (e) {
            e.status
              ? (showSuccessMessage('Success', 'Logging your Account'),
                window.location.reload())
              : showErrorMessage(
                  'Invalid',
                  'You have entered the wrong password or email.'
                );
          },
          error: function (e) {
            if (429 === e.status) {
              const t = e.responseJSON,
                a = parseDuration(t.cooloff_timedelta);
              startCooldown(a);
            }
          },
        });
      } else if (d.length)
        $.ajax({
          type: 'POST',
          headers: { 'X-CSRFToken': e },
          url: '?action=reset_email',
          data: JSON.stringify({ email: d.val().trim() }),
          success: function (e) {
            $('#formContent').empty().append(e);
          },
        });
      else if (r.length && l.length) {
        const t = new URLSearchParams(window.location.search);
        $.ajax({
          type: 'POST',
          headers: { 'X-CSRFToken': e },
          url: '/?action=change_password',
          data: JSON.stringify({
            password1: r.val().trim(),
            password2: l.val().trim(),
            token: t.get('token'),
          }),
          success: function (e) {
            if (e.status)
              return (
                showSuccessMessage(
                  'Password Changed',
                  'Login with your new values'
                ),
                void $('#formContent').empty().append(e.html)
              );
            showErrorMessage('Password Not Changed', 'Kindly Try again.');
          },
        });
      }
    }),
    $('main').on(
      'input',
      '#email, #reset_email',
      debounce(function (e) {
        const t = e.target.value.trim().toLowerCase();
        ($(this).val(t),
          checkEmail(t)
            ? clearOutput()
            : showOutput('Kindly Enter a valid Email'));
      })
    ));
  let t = [];
  ($('main').on('input', '.numeric-input', function () {
    let e = $(this),
      a = e.val().replace(/[^0-9]/g, '');
    (e.val(a),
      (a = $(this).val()),
      1 == a.length && e.next().length && e.next().focus(),
      $('.numeric-input').each((e, a) => {
        let o = a.value.trim();
        t.push(o);
      }),
      $('.otpFullValue').val(t.join('')),
      (t = []));
  }),
    $('main').on('keydown', '.numeric-input', function (e) {
      let t = $(this);
      'Backspace' == e.key &&
        t.prev().length &&
        0 == t.val().length &&
        (e.preventDefault(), t.prev().focus());
    }),
    $('main').on(
      'input',
      '#password1, #reppassword1',
      debounce(function (e) {
        let t = e.target.value.trim();
        $(this).val(t);
        const a = validatePassword(t);
        a ? showOutput(a) : clearOutput();
      })
    ),
    $('main').on(
      'input',
      '#password2, #reppassword2',
      debounce(function (e) {
        let t = e.target.value.trim(),
          a = 'password2' === e.target.id ? '#password1' : '#reppassword1';
        t === $(a).val()
          ? clearOutput()
          : showOutput('Passwords do not match.');
      })
    ));
});
